import{z as i,x as o,o as B,c as d,q as n,j as l,D as e,d as A,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"ETF 工程案例与收束","description":"","frontmatter":{"title":"ETF 工程案例与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/etf-case-map.md","filePath":"quant/etf-case-map.md","lastUpdated":1791063341000}'),F={name:"quant/etf-case-map.md"};function p(f,E,T,u,C,h){const t=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="etf-工程案例与收束" tabindex="-1">ETF 工程案例与收束 <a class="header-anchor" href="#etf-工程案例与收束" aria-label="Permalink to &quot;ETF 工程案例与收束&quot;">​</a></h1><div class="epigraph"><p>三个市场的失败案例讲的是同一句话：价格纪律只在管道最宽的一环内有效，而管道的宽度由最窄的一环决定。</p><footer>—— 案例机制据 Kirilenko, Kyle, Samadi and Tuzun, Journal of Finance, 2017 与 Cheng and Madhavan, Financial Analysts Journal, 2009 整理</footer></div><p><a href="/quant/etf-portfolio-use">上一课</a>把 ETF 放进组合的实施流程。本课先看三个压力案例——机制在极端条件下如何失效，再按课程链条收束。本课是「ETF 与指数工程」的最后一课，前面的课默认申赎、误差、再平衡与载体选型都已读过；本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>案例一，2010 年 5 月 6 日的闪崩。做市商避险撤单、部分成分停牌或报价失真，套利带宽的四壁同时加厚：篮子不再可复制、可比价，ETF 的成交价先于基本面失真，大量成交落在远离价值的价位上。事后统计里 ETF 占了当日的异常成交大头，见<a href="/quant/flash-crash-2010">2010 闪电崩盘</a>。失效的不是申赎制度，而是它的前提——「篮子此刻可成交」。案例二，杠杆与反向 ETP 的每日再定标。规则要求每天收盘前把杠杆调回倍数，产生方向固定、时点公开的机械交易流；波动率高时这笔流自己推动市场，见<a href="/quant/vol-etp-rebalance-flow">Vol ETP 每日再平衡流</a>。案例三，比特币现货 ETF 的溢价。币的托管与可得性约束使创建管道窄于股票 ETF，需求涌入时溢价长期存在，见<a href="/quant/btc-etf-basis">比特币现货 ETF 基差</a>。</p><p><span class="marginnote">术语翻译：授权参与商（AP）就是少数有资格在一级市场「批发」ETF 份额的机构——拿一篮子股票换新份额叫创建，拿份额换回篮子叫赎回。普通投资者只能在二级市场买卖；ETF 价格纪律之所以存在，全靠这条批发管道还开着。</span></p><p><span class="marginnote">杠杆 ETP 的长期回报不等于杠杆乘指数回报：每日再定标在波动中产生路径损耗，\\(n\\) 倍杠杆两日累计收益是 \\(\\prod_t (1 + n r_t) - 1\\) 而非 \\(n \\sum_t r_t\\)。Cheng 与 Madhavan（2009）把这个复利项写成了标准分解——持有人把它当成「追踪失败」，其实是持有方式与产品设计的错配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个案例用同一把尺读。先找管道：案例一的管道是可复制篮子，案例二的是收盘前定标的执行窗口，案例三的是创建单位的币源。再问谁被挤出：闪崩里是被强平与止损的单，ETP 里是与定标流对手的短线交易者，BTC ETF 里是买不到篮子的套利者。最后落到持有人：验收清单因此多出三行——压力日的申赎开放状态、再定标流的日历、底层资产的托管可得性。这三行在平静市场里全是一致通过，在压力日里才是真实的区别；把平静期的折溢价统计当风险证明，正是三个案例共同的起点。</p>',9)),(B(),l(s,null,{default:e(()=>[r(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASE%5B%22%E5%8E%8B%E5%8A%9B%E6%9D%A1%E4%BB%B6%E5%87%BA%E7%8E%B0%22%5D%20--%3E%20PIPE%7B%22%E7%AE%A1%E9%81%93%E6%9C%80%E7%AA%84%E4%B8%80%E7%8E%AF%E5%8F%AF%E9%80%9A%E8%A1%8C%3F%22%7D%0A%20%20PIPE%20--%3E%7C%E6%98%AF%7C%20OK%5B%22%E7%BA%AA%E5%BE%8B%E4%BF%9D%E6%8C%81%EF%BC%9A%E5%B8%A6%E5%AE%BD%E5%86%85%E6%94%B6%E6%95%9B%22%5D%0A%20%20PIPE%20--%3E%7C%E5%90%A6%7C%20FAIL%5B%22%E7%BA%AA%E5%BE%8B%E5%A4%B1%E6%95%88%EF%BC%9A%E6%8A%98%E6%BA%A2%E4%BB%B7%E5%A4%B1%E6%8E%A7%22%5D%0A%20%20FAIL%20--%3E%20W1%5B%22%E7%AF%AE%E5%AD%90%E4%B8%8D%E5%8F%AF%E5%A4%8D%E5%88%B6%EF%BC%9A%E9%97%AA%E5%B4%A9%E5%BC%8F%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20FAIL%20--%3E%20W2%5B%22%E5%AE%9A%E6%A0%87%E6%B5%81%E6%8B%A5%E6%8C%A4%EF%BC%9A%E6%9C%BA%E6%A2%B0%E5%86%B2%E5%87%BB%22%5D%0A%20%20FAIL%20--%3E%20W3%5B%22%E5%BA%95%E5%B1%82%E4%B8%8D%E5%8F%AF%E5%BE%97%EF%BC%9A%E6%BA%A2%E4%BB%B7%E9%95%BF%E5%AD%98%22%5D%0A%20%20W1%20--%3E%20LESS%5B%22%E9%AA%8C%E6%94%B6%E6%B8%85%E5%8D%95%EF%BC%9A%E5%8E%8B%E5%8A%9B%E6%97%A5%E7%8A%B6%E6%80%81%22%5D%0A%20%20W2%20--%3E%20LESS%0A%20%20W3%20--%3E%20LESS%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[A("案例合起来给出本课程的收束命题。ETF 的一切价格纪律都由可执行性供给：指数规则决定需求，申赎管道决定供给弹性，带宽是两者的均衡价格。案例一的带宽被「篮子失真」撕开，案例二被「时点拥挤」顶穿，案例三被「底层不可得」长期垫高——同一机制的三种故障模式。因此ETF 工程不是产品说明书，而是一份前提清单：篮子可复制、申赎开放、结算可行、底层可得，每一项都要在压力状态下重验。机制透明是这套体系的优点也是它的代价：规则公开意味着需求可预测，可预测意味着拥挤与抢跑如影随形，这一点在"),a("a",{href:"/quant/etf-rebalance-effects"},"指数再平衡的效应"),A("里已经账面化。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：指数第一天涨 10%、第二天跌 9.09%，正好回到原点。2 倍杠杆 ETP 两天是 +20% 与 −18.18%，累计约 −1.8%——指数没动，杠杆份额亏了。波动越大、持有越久，这个复利缺口越大，与「追踪好坏」无关。")],-1)),(B(),l(s,null,{default:e(()=>[r(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E9%97%AA%E5%B4%A9%E5%BC%80%E5%A7%8B%3A%20%E8%AE%A2%E5%8D%95%E6%B5%81%E5%A4%B1%E8%A1%A1%22%5D%20--%3E%20W%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E9%81%BF%E9%99%A9%E6%92%A4%E5%8D%95%22%5D%0A%20%20W%20--%3E%20H%5B%22%E9%83%A8%E5%88%86%E6%88%90%E5%88%86%E5%81%9C%E7%89%8C%E6%88%96%E6%8A%A5%E4%BB%B7%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20H%20--%3E%20B%5B%22%E7%AF%AE%E5%AD%90%E6%97%A0%E6%B3%95%E6%8C%89%E5%8F%AF%E4%BB%B7%E6%A0%BC%E5%A4%8D%E5%88%B6%22%5D%0A%20%20B%20--%3E%20A%5B%22AP%20%E5%81%9C%E6%AD%A2%E7%94%B3%E8%B5%8E%E5%A5%97%E5%88%A9%22%5D%0A%20%20A%20--%3E%20E%5B%22ETF%20%E4%BB%B7%E6%A0%BC%E5%A4%B1%E5%8E%BB%E9%94%9A%22%5D%0A%20%20E%20--%3E%20X%5B%22%E5%BC%82%E5%B8%B8%E6%88%90%E4%BA%A4%E9%9B%86%E4%B8%AD%E5%9C%A8%20ETF%20%E4%B8%8A%22%5D%0A%20%20X%20-.-%3E%7C%22%E7%86%94%E6%96%AD%E6%9A%82%E5%81%9C%E5%90%8E%E9%80%90%E6%AD%A5%E6%81%A2%E5%A4%8D%22%7C%20B%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>边界也要收口：三个案例是故障模式的样本，不是故障目录——误差分解的日常工程、证券借贷的收益侧、清单调整的操作细节各有专课；「管道最窄一环」是定性判据，带宽的量级要回到申赎与套利各课的成本模型里算。案例也只解释纪律为什么失效，不预测下一次失效在哪一天——把三行验收清单当日常体检而非危机预警，是本课能给出的全部承诺。</p><p><span class="marginnote">直觉类比：「管道最窄一环」像高峰期的地铁站——平时每站都宽，人流通行无感；一旦最窄的闸机口堵住（篮子不可成交、申赎暂停），整条线的通行时间就由那一个闸机决定，而不是由各站的平均宽度决定。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>闪崩、杠杆 ETP 定标流、BTC ETF 溢价是同一机制的三种故障：管道最窄一环决定纪律边界。</li><li>案例一败在篮子可复制性，案例二败在定标时点拥挤，案例三败在底层可得性。</li><li>杠杆 ETP 的路径损耗是复利结构，不是追踪失败；长期持有前先读再定标条款。</li><li>验收清单要加压力日三行：申赎状态、定标日历、托管可得性。</li><li>课程链条收束：构建规则、申赎套利、误差分解、再平衡效应、因子产品化、衍生载体、组合应用，全部回到「可执行性供给价格纪律」这一句。</li><li>出处：Kirilenko, Kyle, Samadi and Tuzun, <em>Journal of Finance</em>, 2017；Cheng and Madhavan, <em>Financial Analysts Journal</em>, 2009；案例数据口径见<a href="/quant/flash-crash-2010">2010 闪电崩盘</a>、<a href="/quant/vol-etp-rebalance-flow">Vol ETP 每日再平衡流</a>与<a href="/quant/btc-etf-basis">比特币现货 ETF 基差</a>。</li></ul>',5))])}const c=i(F,[["render",p]]);export{D as __pageData,c as default};
